mod common;

use common::Harness;
use serde_json::json;

fn create(h: &mut Harness, name: &str, attributes: serde_json::Value) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes}));
}

fn send(h: &mut Harness, body: &str) -> serde_json::Value {
    h.run(json!({"Command": "SendMessage", "QueueName": "q", "Body": body}))
}

#[test]
fn limit_counts_utf8_bytes_inclusively() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 4}));
    assert_eq!(send(&mut h, "abcd")["ok"], true);
    assert_eq!(send(&mut h, "é é")["ok"], false); // 5 bytes, 3 chars
    assert_eq!(send(&mut h, "éé")["ok"], true); // 4 bytes
    assert_eq!(send(&mut h, "abcde")["error"]["code"], "InvalidParameterValue");
}

#[test]
fn size_rule_comes_after_lookup_and_before_rule_one() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"MaxMessageBytes": 1}));
    let missing_queue = h.err(json!({"Command": "SendMessage", "QueueName": "nope", "Body": "xx"}));
    assert_eq!(missing_queue, "QueueDoesNotExist");
    // A standard queue given GroupId would be UnsupportedOperation, but the size rule wins.
    let code = h.err(
        json!({"Command": "SendMessage", "QueueName": "q", "Body": "xx", "GroupId": "g"}),
    );
    assert_eq!(code, "InvalidParameterValue");
}

#[test]
fn attribute_defaults_range_and_get() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let get = |h: &mut Harness| {
        h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Attributes"]
            ["MaxMessageBytes"]
            .clone()
    };
    assert_eq!(get(&mut h), 1024);
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        let code = h.err(
            json!({"Command": "CreateQueue", "QueueName": "r", "Attributes": {"MaxMessageBytes": bad}}),
        );
        assert_eq!(code, "InvalidParameterValue");
    }
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 7}}));
    assert_eq!(get(&mut h), 7);
    // CreateQueue rule 4: differing MaxMessageBytes is a different queue.
    let code = h.err(
        json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 8}}),
    );
    assert_eq!(code, "QueueAlreadyExists");
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 7}}));
}

#[test]
fn lowering_limit_keeps_existing_messages() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    assert_eq!(send(&mut h, "long body")["ok"], true);
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 2}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
}

#[test]
fn dead_letter_moves_ignore_limit() {
    let mut h = Harness::new();
    create(&mut h, "dlq", json!({"MaxMessageBytes": 1}));
    create(&mut h, "q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1, "VisibilityTimeout": 0}));
    assert_eq!(send(&mut h, "toolong")["ok"], true);
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dlq"}));
    assert_eq!(r["Messages"][0]["Body"], "toolong");
}
