mod common;

use common::Harness;
use serde_json::{Value, json};

fn setup() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tag(h: &mut Harness, tags: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": tags}))
}

fn tags(h: &mut Harness) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": "q"}))["Tags"].clone()
}

#[test]
fn tag_replace_untag_and_list() {
    let mut h = setup();
    assert_eq!(tags(&mut h), json!({}));
    assert_eq!(tag(&mut h, json!({"a": "1", "B": ""})), json!({"ok": true}));
    assert_eq!(tag(&mut h, json!({"a": "2"})), json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"a": "2", "B": ""}));
    let r = h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz"]}));
    assert_eq!(r, json!({"ok": true}));
    assert_eq!(tags(&mut h), json!({"B": ""}));
    assert_eq!(tag(&mut h, json!({})), json!({"ok": true}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
}

#[test]
fn invalid_keys_and_values() {
    let mut h = setup();
    let bad_key_128 = "k".repeat(129);
    for t in [
        json!({"": "v"}),
        json!({"a b": "v"}),
        json!({bad_key_128: "v"}),
        json!({"a": 1}),
        json!({"a": null}),
        json!({"a": "x".repeat(257)}),
        json!({"ok": "v", "é": "v"}),
    ] {
        assert_eq!(tag(&mut h, t.clone())["error"]["code"], "InvalidParameterValue", "{t}");
    }
    assert_eq!(tags(&mut h), json!({}));
    assert_eq!(tag(&mut h, json!({"k".repeat(128): "é".repeat(128)}))["ok"], true);
    assert_eq!(tag(&mut h, json!({"é": "v"}))["ok"], false);
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})), "InvalidParameterValue");
    for keys in [json!({}), json!([1]), json!(["a b"]), json!([""])] {
        let code = h.err(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": keys}));
        assert_eq!(code, "InvalidParameterValue");
    }
}

#[test]
fn value_limit_is_in_bytes() {
    let mut h = setup();
    assert_eq!(tag(&mut h, json!({"a": "é".repeat(128)}))["ok"], true); // 256 bytes
    assert_eq!(tag(&mut h, json!({"a": "é".repeat(129)}))["ok"], false);
}

#[test]
fn missing_params_and_check_order() {
    let mut h = setup();
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "Tags": {}})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "ListQueueTags"})), "MissingParameter");
    // Value errors (step 3) precede the lookup (step 4).
    let code = h.err(json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {"a": 1}}));
    assert_eq!(code, "InvalidParameterValue");
    for c in [
        json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}}),
        json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []}),
        json!({"Command": "ListQueueTags", "QueueName": "nope"}),
    ] {
        assert_eq!(h.err(c), "QueueDoesNotExist");
    }
}

#[test]
fn fifty_tag_limit() {
    let mut h = setup();
    let many = |range: std::ops::Range<u32>| {
        Value::Object(range.map(|i| (format!("k{i}"), json!("v"))).collect())
    };
    assert_eq!(tag(&mut h, many(0..50))["ok"], true);
    assert_eq!(tag(&mut h, many(0..51))["error"]["code"], "LimitExceeded");
    assert_eq!(tag(&mut h, json!({"new": "v"}))["error"]["code"], "LimitExceeded");
    // Replacing existing keys is fine at the limit, and a failed command changes nothing.
    assert_eq!(tag(&mut h, json!({"k0": "changed"}))["ok"], true);
    assert_eq!(tags(&mut h).as_object().unwrap().len(), 50);
    assert_eq!(tags(&mut h)["k0"], "changed");
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k1"]}));
    assert_eq!(tag(&mut h, json!({"new": "v"}))["ok"], true);
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = setup();
    tag(&mut h, json!({"a": "1"}));
